<script setup lang="ts">
import { computed } from 'vue'
import type { EvidenceContribution, EvidenceContributions, KnowledgeProposal } from '../knowledgeApi'
const props = defineProps<{ contributions?: EvidenceContributions; proposals?: KnowledgeProposal[]; canRescore: boolean; disabled: boolean }>()
const emit = defineEmits<{ proposal: [KnowledgeProposal] }>()
const groups = computed(() => [{ id: 'sources', label: 'Vulnerability sources', entries: props.contributions?.vulnerability_sources || [] }, { id: 'analyses', label: 'Vulnerability analyses', entries: props.contributions?.vulnerability_analyses || [] }])
const label = (value: string) => value.replaceAll('_', ' ')
const proposal = (entry: EvidenceContribution) => typeof entry.claims.proposal_id === 'string' ? props.proposals?.find(item => item.id === entry.claims.proposal_id) : undefined
const facts = (entry: EvidenceContribution) => Array.isArray(entry.claims.contributes) ? entry.claims.contributes.filter((item): item is string => typeof item === 'string').map(label).join(' · ') : ''
const ratings = (entry: EvidenceContribution) => entry.ratings.map(item => item.score == null ? item.severity || 'Unrated' : `${item.score.toFixed(1)}${item.method ? ` ${item.method}` : ''}`).join(' / ')
</script>
<template>
  <section class="contributions" aria-label="Evidence contributions">
    <section v-for="group in groups" :key="group.id" class="contribution-group" :aria-label="group.label"><h3>{{ group.label }} <span>{{ group.entries.length }}</span></h3><p v-if="!group.entries.length" class="hint">{{ contributions ? 'No contributions recorded.' : 'Classified contribution summary unavailable; retained raw evidence remains available below.' }}</p>
      <article v-for="entry in group.entries" :key="entry.id" class="contribution-entry"><div class="contribution-overview"><div><strong>{{ entry.label || entry.provider }}</strong><small>{{ label(entry.status) }}<template v-if="entry.current === false"> · Historical inputs</template><template v-if="entry.current === null"> · Currency unspecified</template></small></div><div class="contribution-score"><span v-if="entry.proposal">{{ entry.proposal.base_score?.toFixed(1) ?? '—' }} → <strong>{{ entry.proposal.score?.toFixed(1) ?? 'Withheld' }}</strong><small>Scoring proposal</small></span><span v-else-if="entry.ratings.length">{{ ratings(entry) }}</span><span v-else-if="entry.claims.proposed_applicability">Applicability: {{ label(String(entry.claims.proposed_applicability)) }}</span><span v-else class="hint">No score supplied</span></div><div class="contribution-use"><span v-if="group.id === 'sources'">{{ facts(entry) || 'Source evidence' }}</span><span v-else>{{ entry.proposal || entry.claims.proposed_applicability ? 'Proposal only' : 'Analysis evidence' }}</span><small v-if="entry.adoption.status === 'referenced'">Referenced in assessment</small><small v-if="entry.adoption.published_score">Linked published score</small><button v-if="canRescore && proposal(entry)" :disabled="disabled || entry.claims.eligible !== true || !proposal(entry)?.eligible" @click="emit('proposal', proposal(entry)!)">Use proposal</button></div></div>
        <p v-if="entry.summary" class="contribution-summary">{{ entry.summary }}</p><details><summary>Evidence, limitations and provenance</summary><p v-if="group.id === 'analyses' && !entry.adoption.published_score" class="hint">No publication link recorded.</p><p v-if="entry.claims.description" class="contribution-reasoning">{{ entry.claims.description }}</p><p v-if="entry.claims.proposed_applicability">Applicability proposal: {{ label(String(entry.claims.proposed_applicability)) }}</p><p v-if="entry.claims.verdict">Provider verdict: {{ entry.claims.verdict }}</p><p v-if="entry.claims.summary" class="contribution-reasoning">{{ entry.claims.summary }}</p><dl v-if="group.id === 'analyses'" class="analysis-eligibility"><template v-if="typeof entry.claims.application_eligible === 'boolean'"><dt>Applicability proposal</dt><dd>{{ entry.claims.application_eligible ? 'Eligible' : 'Withheld' }}</dd></template><template v-if="typeof entry.claims.eligible === 'boolean'"><dt>Scoring proposal</dt><dd>{{ entry.claims.eligible ? 'Eligible' : 'Withheld' }}</dd></template><template v-if="entry.claims.confidence"><dt>Provider confidence claim</dt><dd>{{ entry.claims.confidence }}</dd></template></dl><p v-if="entry.claims.rationale" class="contribution-reasoning">{{ entry.claims.rationale }}</p><ul v-if="entry.diagnostics.length"><li v-for="item in entry.diagnostics" :key="item">{{ label(item) }}</li></ul><p v-if="entry.adoption.assessment_revisions.length">Referenced assessment revisions: <code v-for="revision in entry.adoption.assessment_revisions" :key="revision">{{ revision }}</code></p><ul v-if="entry.ratings.length"><li v-for="(rating, index) in entry.ratings" :key="index">{{ rating.method || 'Unspecified method' }} · {{ rating.score ?? rating.severity ?? 'Unrated' }}<code v-if="rating.vector">{{ rating.vector }}</code></li></ul><details v-if="entry.proposal"><summary>Proposed vectors</summary><pre>{{ JSON.stringify(entry.proposal, null, 2) }}</pre></details><details><summary>Exact claims and provenance</summary><pre>{{ JSON.stringify({ kind: entry.kind, provider: entry.provider, claims: entry.claims, provenance: entry.provenance, adoption: entry.adoption }, null, 2) }}</pre></details></details>
      </article>
    </section><details v-if="contributions?.limitations.length" class="contribution-limits"><summary>Contribution limits</summary><ul><li v-for="item in contributions.limitations" :key="item">{{ item }}</li></ul></details>
  </section>
</template>
<style scoped>
.contributions{min-width:0}.contribution-group{margin:10px 0}.contribution-group h3{font-size:.84rem;margin:0 0 5px}.contribution-group h3 span{color:var(--muted);font-weight:400}.contribution-entry{border-top:1px solid var(--line);padding:7px 0;min-width:0}.contribution-overview{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(85px,.7fr) minmax(100px,1fr);gap:8px;align-items:start;font-size:.78rem}.contribution-overview>div{min-width:0;overflow-wrap:anywhere}.contribution-overview small{font-size:.69rem;margin-top:2px}.contribution-score{font-variant-numeric:tabular-nums}.contribution-use{font-size:.72rem}.contribution-use button{font-size:.7rem;padding:2px 5px;margin-top:4px}.contribution-summary{font-size:.78rem;line-height:1.45;margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.contribution-entry:has(>details[open])>.contribution-summary{display:block}.contribution-entry details{margin:4px 0;font-size:.75rem}.contribution-entry summary{font-size:.72rem}.analysis-eligibility{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:3px 8px}.analysis-eligibility dd{margin:0}.analysis-eligibility dt{color:var(--muted)}.contribution-reasoning{white-space:pre-wrap;max-height:28vh;overflow:auto}.contributions pre,.contributions code{overflow-wrap:anywhere;font-size:.7rem}.contributions code{display:block}.contributions pre{max-height:35vh;overflow:auto}.contribution-limits{font-size:.75rem}.hint{font-size:.75rem;margin:4px 0;color:var(--muted)}@media(max-width:550px){.contribution-overview{grid-template-columns:minmax(0,1fr) minmax(78px,.65fr)}.contribution-use{grid-column:1/-1;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.contribution-use small{margin:0}}
</style>
